package glitch

import data.glitch_lib

credential_keywords := {"password", "passwd", "pwd", "secret", "token", "api_key", "apikey", "access_key", "secret_key", "credentials", "auth_token", "bearer", "jwt", "private_key", "public_key", "ssh_key", "cert", "certificate", "key_pem", "key_data", "encryption_key", "decryption_key", "connection_string", "dsn", "jdbc_url", "database_url", "mongo_uri", "redis_url", "webhook_secret", "signing_secret", "hmac_key", "shared_secret", "client_secret"}

high_entropy_pattern := "^[A-Za-z0-9+/=]{20,}$|^[0-9a-fA-F]{20,}$|(?i)^(BEGIN|END)\\s+(RSA|DSA|EC|OPENSSH)\\s+(PRIVATE|PUBLIC)\\s+KEY"

pem_pattern := "(?i)-----BEGIN\\s+(RSA|DSA|EC|OPENSSH)\\s+(PRIVATE|PUBLIC)\\s+KEY-----"

default_weak_values := {"admin", "password", "123456", "default", "root", "toor", "guest", "changeme", "change_me", "temp", "temporary"}

# Check if field name matches credential keywords
name_matches_credential(name) {
    lower_name := lower(name)
    keyword := credential_keywords[_]
    contains(lower_name, keyword)
}

# Check if value appears to be a high-entropy secret (base64, hex, PEM)
is_high_entropy_secret(value) {
    regex.match(high_entropy_pattern, value)
}

# Check if value contains PEM structure
is_pem_structure(value) {
    regex.match(pem_pattern, value)
}

# Check if value is a weak default credential
is_weak_default(value) {
    lower_val := lower(value)
    lower_val == default_weak_values[_]
}

# Check if value is a literal credential (not a reference)
is_literal_credential_value(value) {
    value.ir_type == "String"
    value.value != ""
    not references_secure_source(value)
}

# Check if value references secure external source
references_secure_source(value) {
    value.ir_type == "FunctionCall"
    fn_name := lower(value.name)
    contains(fn_name, "data")
} else {
    value.ir_type == "FunctionCall"
    fn_name := lower(value.name)
    contains(fn_name, "vault")
} else {
    value.ir_type == "FunctionCall"
    fn_name := lower(value.name)
    contains(fn_name, "secret")
} else {
    value.ir_type == "FunctionCall"
    fn_name := lower(value.name)
    contains(fn_name, "var")
} else {
    value.ir_type == "FunctionCall"
    fn_name := lower(value.name)
    contains(fn_name, "lookup")
} else {
    value.ir_type == "MethodCall"
} else {
    value.ir_type == "VariableReference"
}

# Recursively check nested structures for literal credentials
check_nested_for_credential(attr_name, value) {
    value.ir_type == "String"
    is_literal_credential_value(value)
    name_matches_credential(attr_name)
} else {
    value.ir_type == "String"
    is_literal_credential_value(value)
    is_high_entropy_secret(value.value)
} else {
    value.ir_type == "String"
    is_literal_credential_value(value)
    is_pem_structure(value.value)
} else {
    value.ir_type == "Hash"
    some k, v
    value.value[k] = v
    check_nested_for_credential(attr_name, v)
} else {
    value.ir_type == "Array"
    some i
    check_nested_for_credential(attr_name, value.value[i])
}

# Check for credential structure with literals (username/password pairs)
is_credential_structure_with_literals(value) {
    value.ir_type == "Hash"
    has_credential_field(value)
    has_literal_string(value)
}

has_credential_field(hash) {
    some k, _
    lower_k := lower(k)
    name_matches_credential(lower_k)
}

has_literal_string(hash) {
    some _, v
    v.ir_type == "String"
    v.value != ""
    not references_secure_source(v)
}

# Main detection: Attribute with credential name and literal value
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""

    vars := glitch_lib.all_variables(parent)
    var := vars[_]

    name_matches_credential(var.name)
    is_literal_credential_value(var.value)

    result := {
        "type": "sec_hard_secr",
        "element": var,
        "path": parent.path,
        "description": "Use of hard-coded credentials - Credentials should not be hard-coded in configuration files. (CWE-798)"
    }
}

Glitch_Analysis[result] {
